select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"native_identity_key":"nlscale:20261102:ol:OL14877416W"},"seq":1,"relation":"works","after_row":{"id":987158001,"title":"Lady Windermere''s fan","cover_id":null,"author_id":977300022,"work_type":null,"source_type":"open_library","open_library_id":"OL14877416W","first_publish_year":1893,"native_identity_key":"nlscale:20261102:ol:OL14877416W"},"before_row":null},{"key":{"open_library_edition_id":"OL12852236M"},"seq":2,"relation":"editions","after_row":{"id":987258001,"title":"Lady Windermere''s Waaier","isbn_10":null,"isbn_13":"9789077932018","work_id":987158001,"cover_id":null,"language":"dut","publisher":"Uitgeverij Diderot","publish_date":null,"open_library_edition_id":"OL12852236M"},"before_row":null},{"key":{"work_id":987158001,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"Lady Windermere bereidt een feest voor haar verjaardag voor wanneer zij hoort dat haar man geld geeft aan een raadselachtige vrouw. Zijn ontkenning neemt haar argwaan niet weg. Als mevrouw Erlynne vervolgens op het bal verschijnt, dreigen jaloezie en gekrenkte trots haar huwelijk te ontwrichten. Lord Darlington biedt een uitweg die nieuwe risico’s meebrengt. In deze toneelkomedie botsen de keurige regels van de Londense samenleving met wat mensen werkelijk doen. Een verloren waaier kan daarbij meer onthullen dan een openhartig gesprek.","work_id":987158001,"evidence":[{"note":"OscarWilde four-act stageplay, not novel or adaptation. ExactDutchPaperback9789077932018, confirmed sourceparent/author/KB Dutchprint. Firstprint1893 distinguished from1892stageproduction. Unsupported play type kept null under existingmodel.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p277353548"],"reference":"new-work-dossier-readings-059.json#173","checked_at":"2026-11-03T12:02:51.451Z"},{"type":"original_substantive_source_review","review":"content-amendment-024