ce_type":"open_library","open_library_id":"OL15266417W","first_publish_year":2008,"native_identity_key":"nlscale:20261102:ol:OL15266417W"},"before_row":null},{"key":{"open_library_edition_id":"OL17083586M"},"seq":6,"relation":"editions","after_row":{"id":987258002,"title":"Verscheur deze brief! : ik vertel veel te veel : een briefwisseling","isbn_10":null,"isbn_13":"9789023425939","work_id":987158002,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL17083586M"},"before_row":null},{"key":{"work_id":987158002,"language":"nl"},"seq":7,"relation":"catalog_work_descriptions","after_row":{"text":"Willem Frederik Hermans en Gerard Reve bespreken in hun brieven elkaars verhalen, hun plannen en hun plaats in de Nederlandse literatuur. De jonge schrijvers herkennen iets in elkaar, maar verschillen steeds sterker in levenshouding en werkwijze. Ook Reves poging in het Engels te schrijven komt ter sprake. De correspondentie laat zien hoe wederzijdse aandacht geleidelijk plaatsmaakt voor irritatie en verwijdering. Latere brieven volgen op de breuk. Toelichtingen van de bezorgers plaatsen hun opmerkingen over boeken en persoonlijke gebeurtenissen in context.","work_id":987158002,"evidence":[{"note":"Reciprocal correspondence of Hermans and Reve, notjointnovel orone-wayselection. ExactDutchHardcover9789023425939,2008, title copied solely from exactISBN-boundKBp307937720; sourceedition omittedtitle. Bothletterwriters and twoeditors roles retained in evidence, one existingprimaryauthor field Hermans, no combinedauthor or merge.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p307937720"],"reference":"new-work-dossier-readings-059.json#190","checked_at":"2026-11-03T12:02:51.451Z"},{"type":"original_substantive_source_review","review":"content-amendment-024.json","sources":["https://www.dbnl.org/tekst/_ons003200801_01/_ons003200801_01_0044.php","https://www.dbnl.org/tekst/_nie012200