3586M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987258002,"bound_title":"Verscheur deze brief! : ik vertel veel te veel : een briefwisseling","reviewed_at":"2026-11-03T12:02:51.451+00:00","bound_isbn13":"9789023425939","evidence_url":"https://data.bibliotheken.nl/id/nbt/p307937720","review_batch":"nl-scale-20261102-059","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":969300005},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL15266456W"},"seq":9,"relation":"works","after_row":{"id":987158003,"title":"Je vriendschap is werkelijk onbetaalbaar","cover_id":null,"author_id":969300005,"work_type":"collection","source_type":"open_library","open_library_id":"OL15266456W","first_publish_year":2004,"native_identity_key":"nlscale:20261102:ol:OL15266456W"},"before_row":null},{"key":{"open_library_edition_id":"OL23958875M"},"seq":10,"relation":"editions","after_row":{"id":987258003,"title":"Je vriendschap is werkelijk onbetaalbaar","isbn_10":null,"isbn_13":"9789023414988","work_id":987158003,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL23958875M"},"before_row":null},{"key":{"work_id":987158003,"language":"nl"},"seq":11,"relation":"catalog_work_descriptions","after_row":{"text":"Willem Frederik Hermans schrijft zijn uitgever Geert van Oorschot over manuscripten, geldzorgen, tijdschriften en de Nederlandse literaire wereld. Hun samenwerking begint met de uitgave van De tranen der acacia’s, maar wordt steeds sterker door ruzies belast. Tussen praktische afspraken en scherpe verwijten door licht Hermans toe hoe zijn werk ontstaat. Deze bundel verzamelt zijn kant van de correspondentie. De brieven zijn bezorgd door Nop Maas en vormen een tegenhanger van de afzonderlijk uitgegeven brieven van Van Oorschot aan Hermans.","work_id":987158003,"evidence":[{"note":"Hermans letters to GeertvanOorschot,2004, separatelyidentified from2003publisherletters. ExactDutchHardcover9789023414988 and sewnboard binding independentlyconfirmed by DBNLbibliography; NopMaaseditor notcoauthor.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p270104151"],"reference":"new-work-dossier-readings-059.json#191","checked_at":"2026-11-03T12:02:51.451Z"},{"type":"original_substantive_source_review","review":"content-amendment-024.json","sources":["https://metadata.isbn.nl/832467/je-vriendschap-is-werkelijk-onbetaalbaar.html","https://www.dbnl.org/tekst/jans037bibl01_01/jans037bibl01_01_0103.php","https://data.bibliotheken.nl/id/nbt/p270104151"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Provider-documented bulkarchive path checked with boundedrange. No verified imagebytes retained; no repeated request, providerdenial or no-cover-existence claim. Actual browserexistingresolver may show exactcover and remains separatelyrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789023414988","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":6277097,"receipt":"cover-archive-v2-readback.json","receiptSha256":"0aab914cb53f16ddbe375255cd8a7bbd1328ee15dada35cc2ea4892f7d6489be"}],"checkedAt":"2026-11-03T12:02:51.451Z","editionKey":"/books/OL23958875M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.dbnl.org/tekst/jans037bibl01_01/jans037bibl01_01_0103.php","reviewed_at":"2026-11-03T12:02:51.451+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-059","r